alter table rental_autopay_enrollments add column if not exists provider_customer_id text;alter table rental_autopay_enrollments add column if not exists activated_at timestamptz;alter table rental_autopay_enrollments add column if not exists last_attempt_at timestamptz;alter table rental_autopay_enrollments add column if not exists consecutive_failures smallint not null default 0;
create table if not exists rental_autopay_attempts(owner_id text not null,id text not null,enrollment_id text not null,charge_id text not null,payment_id text not null,status text not null check(status in('created','submitted','succeeded','failed','requires_action','cancelled')),idempotency_key text not null,provider_payment_id text,failure_code text,failure_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(owner_id,id),unique(owner_id,enrollment_id,charge_id),unique(idempotency_key),foreign key(owner_id,enrollment_id)references rental_autopay_enrollments(owner_id,id),foreign key(owner_id,charge_id)references rent_charges(owner_id,id),foreign key(owner_id,payment_id)references rental_payments(owner_id,id));
alter table rental_autopay_attempts enable row level security;alter table rental_autopay_attempts force row level security;create policy rental_autopay_attempt_owner_read on rental_autopay_attempts for select to authenticated using(owner_id=auth.uid()::text);
create or replace function activate_rental_autopay_from_payment(p_connected_account_id text,p_payment_id text,p_payment_method_id text,p_mandate_id text)returns jsonb language plpgsql security invoker set search_path=public as $$declare p_owner_id text;p rental_payments;e rental_autopay_enrollments;begin select owner_id into p_owner_id from landlord_payment_accounts where provider='stripe'and provider_account_id=p_connected_account_id;if p_owner_id is null then raise exception 'Unknown Stripe connected account.';end if;select * into p from rental_payments where owner_id=p_owner_id and id=p_payment_id;if p.status<>'succeeded'or p_payment_method_id is null then return jsonb_build_object('activated',false);end if;select * into e from rental_autopay_enrollments where owner_id=p_owner_id and tenant_id=p.tenant_id and lease_id=p.lease_id and status='setup_required'order by consented_at desc limit 1;if e.id is null then return jsonb_build_object('activated',false);end if;update rental_autopay_enrollments set status='active',provider_customer_id=p.provider_customer_id,provider_payment_method_id=p_payment_method_id,provider_mandate_id=p_mandate_id,activated_at=now(),updated_at=now()where owner_id=p_owner_id and id=e.id;return jsonb_build_object('activated',true,'enrollment_id',e.id);end$$;
revoke all on function activate_rental_autopay_from_payment(text,text,text,text)from public,anon,authenticated;grant execute on function activate_rental_autopay_from_payment(text,text,text,text)to service_role;
